import{_ as s,C as r,o,c as i,aj as e,E as n}from"./framework.js";const b=JSON.parse('{"title":"Pages | Site | Admin CMS","description":"Manage all accessible page resources in the site: list maintenance, routing, code editing, and inline editing. For page syntax, see Template Engine -> Page. For scripts, see k.site.pages.","frontmatter":{"title":"Pages | Site | Admin CMS","description":"Manage all accessible page resources in the site: list maintenance, routing, code editing, and inline editing. For page syntax, see Template Engine -> Page. For scripts, see k.site.pages.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/site/pages.html"}]]},"headers":[],"relativePath":"cms/site/pages.md","filePath":"en/cms/site/pages.md","lastUpdated":1781010536000}'),d={name:"cms/site/pages.md"};function l(g,t,h,c,p,u){const a=r("DocImage");return o(),i("div",null,[t[0]||(t[0]=e('<h1 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h1><blockquote><p>Menu: top-left <strong>Pages</strong><br> Deep link: <code>/_Admin/site/pages?SiteId={siteGuid}</code></p></blockquote><p>Manage all accessible page resources in the site: list maintenance, routing, code editing, and inline editing. For page syntax, see <a href="/kb-docs/templateEngine/page/">Template Engine -&gt; Page</a>. For scripts, see <a href="/kb-docs/api/site/page.html">k.site.pages</a>.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisite</p><p>It helps to understand <a href="./media.html">Media library</a> and <a href="./dashboard.html">Dashboard</a> first. If you want to create a layout page, prepare at least one layout under <strong>Development -&gt; Layouts</strong> first.</p></div><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><ol><li>Enter a site admin.</li><li>Click <strong>Pages</strong> in the left toolbar.</li><li>The URL is <code>/_Admin/site/pages?SiteId=...</code>.</li></ol>',6)),n(a,{src:"/cms/site/pages-list.png",alt:"Page list",width:"1120"}),t[1]||(t[1]=e('<h2 id="list-page" tabindex="-1">List page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td>Page resource name. The home icon marks the start page or home link.</td></tr><tr><td>Link</td><td>Whether the page is linked from other resources</td></tr><tr><td>Online</td><td>Whether the page is published</td></tr><tr><td>References</td><td>Which layouts, views, or content items use it</td></tr><tr><td>Last modified</td><td>Last save time</td></tr><tr><td>Preview</td><td>The front-end path; open it in a new window</td></tr></tbody></table><p>You can switch between <strong>Pages</strong> and <strong>Page Tree</strong>:</p><ul><li><strong>Pages</strong> is a flat list, better for search, copy, and delete.</li><li><strong>Page Tree</strong> shows hierarchical structure and supports advanced filtering.</li></ul><h2 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Create Page</strong></td><td>Choose a page type and start the creation flow</td></tr><tr><td><strong>Create Designer Page</strong></td><td>Create a visual design page based on a layout</td></tr><tr><td><strong>Import</strong></td><td>Import pages from a package or external source</td></tr><tr><td><strong>Route Settings</strong></td><td>Manage routing rules across multiple pages</td></tr></tbody></table><h2 id="create-page" tabindex="-1">Create page <a class="header-anchor" href="#create-page" aria-label="Permalink to &quot;Create page&quot;">​</a></h2><p>The <strong>Create Page</strong> menu usually includes:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>HTML Page</strong></td><td>Standalone HTML, optional layout</td></tr><tr><td><strong>Rich Text Page</strong></td><td>Content managed through the rich text editor</td></tr><tr><td><strong>{Layout name} Page</strong></td><td>Uses a specific layout and fills its placeholders</td></tr></tbody></table><p>For an <strong>HTML Page</strong>, enter a page name and URL first. For a <strong>Layout Page</strong>, the system also passes <code>layoutId</code>.</p><h2 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h2><p>Each page usually has three entry points:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Doc</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Settings</strong></td><td><a href="./pages-setting.html">Page settings</a></td><td>URL, title, meta, page-level styles/scripts, cache</td></tr><tr><td><strong>Edit Code</strong> / <strong>Design</strong></td><td><a href="./pages-edit-code.html">Edit code</a></td><td>Change the HTML body or open the visual designer</td></tr><tr><td><strong>Inline Edit</strong></td><td><a href="./pages-inline-edit.html">Inline edit</a></td><td>Edit visible text, images, links, and local styles in the rendered page</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Which one should you use?</p><ul><li><strong>Settings</strong> for route, SEO, publish state, and asset references.</li><li><strong>Edit Code</strong> for page structure, placeholders, and view insertion.</li><li><strong>Inline Edit</strong> for small visible content changes on a live page.</li></ul></div><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li>Create an HTML page or a layout page.</li><li>Use <a href="./pages-edit-code.html">Edit code</a> to add structure.</li><li>Use <a href="./pages-setting.html">Page settings</a> to confirm URL and publish state.</li><li>Preview the page.</li><li>Use <a href="./pages-inline-edit.html">Inline edit</a> for later content tweaks.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./dashboard.html">Dashboard</a></td><td>Page totals in My Resources</td></tr><tr><td><a href="./media.html">Media library</a></td><td>Images used in pages</td></tr><tr><td><a href="./../content/contents-folders-list.html">Content folders</a></td><td>Often paired with detail pages</td></tr></tbody></table>',18))])}const f=s(d,[["render",l]]);export{b as __pageData,f as default};
